def construct_eml_polynomial(coefficients):
    n = len(coefficients)
    if n == 0:
        return lambda x: 0.0
    def horner_eval(x):
        result = coefficients[-1]
        for i in range(n - 2, -1, -1):
            result = coefficients[i] + x * result
        return result
    return horner_eval

import math
def iterated_exponential(k, x):
    result = x
    for _ in range(k):
        if result > 700:
            return float('inf')
        result = math.exp(result)
    return result
